#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <string.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define MSG_SIZE 32

static K_MBOX_DEFINE(mbox);

/* Not used in all tests, but common for mbox tests */
static char __aligned(4) tdata[MSG_SIZE];
static char __aligned(4) rdata[MSG_SIZE];

static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static struct k_thread tthread;

static K_SEM_DEFINE(sync_sem, 0, 1);

/* Test data for buffer tests */
static const char * const data[] = {
    "hello",
    "world_long_string_that_is_longer_than_hello",
    "short",
    "another_long_string_to_test_buffer_handling_properly",
    "final_message"
};

enum info_type {
    INFO_TYPE_HELLO = 0,
    INFO_TYPE_WORLD,
    INFO_TYPE_SHORT,
    INFO_TYPE_ANOTHER,
    INFO_TYPE_FINAL,
    INFO_TYPE_COUNT
};

static void tmbox_put(enum info_type info_type, k_timeout_t timeout)
{
    struct k_mbox_msg msg;

    msg.info = info_type;
    /* Fix: Use strlen + 1 for string buffer size, not sizeof(char*) */
    msg.size = strlen(data[info_type]) + 1;
    msg.tx_data = (void *)data[info_type];
    msg.tx_block = K_NO_WAIT; /* For async put, block is not used for data */
    msg.rx_block = K_NO_WAIT; /* Not relevant for put */

    k_mbox_async_put(&mbox, &msg, NULL);
}

static void tmbox_get(enum info_type info_type, k_timeout_t timeout)
{
    struct k_mbox_msg mmsg;
    void *rx_data;

    k_mbox_get(&mbox, &mmsg, &rx_data, timeout);

    zassert_equal(mmsg.info, info_type, "mmsg.info not equal to info_type");
    /* Fix: Compare received size against actual string length + 1 */
    zassert_equal(mmsg.size, strlen(data[info_type]) + 1, "mmsg.size not equal to strlen(data[info_type]) + 1");
    zassert_equal(mmsg.rx_data, rx_data, "mmsg.rx_data not equal to rx_data");

    /* For async put, rx_data points to the original buffer, so direct comparison is fine. */
    zassert_true(strcmp((char *)rx_data, data[info_type]) == 0, "Received data mismatch");
}

static void tthread_entry_async_put_get_buffer(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    for (enum info_type i = 0; i < INFO_TYPE_COUNT; i++) {
        tmbox_get(i, K_FOREVER);
        k_sem_give(&sync_sem); /* Signal that get is done */
    }
}

ZTEST_DMEM_DEFINE(mbox_api);

ZTEST_USER_F(mbox_api, test_mbox_async_put_get_buffer)
{
    k_thread_create(&tthread, tstack, STACK_SIZE,
                    tthread_entry_async_put_get_buffer, NULL, NULL, NULL,
                    K_PRIO_COOP(7), 0, K_NO_WAIT);
    k_thread_name_set(&tthread, "tthread_async_put_get_buffer");

    for (enum info_type i = 0; i < INFO_TYPE_COUNT; i++) {
        tmbox_put(i, K_NO_WAIT); /* Put asynchronously */
        k_sem_take(&sync_sem, K_FOREVER); /* Wait for get to complete */
    }

    k_thread_join(&tthread, K_FOREVER);
}

static K_MBOX_DEFINE(multi_mbox[2]);

ZTEST_USER_F(mbox_api, test_define_multi_mbox)
{
    /* Just test that it compiles and links */
    zassert_true(true, "This test just checks compilation/linking");
}

static void tthread_entry_async_multiple_put(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    struct k_mbox_msg msg;
    char tx_buf[MSG_SIZE];

    for (int i = 0; i < 3; i++) {
        snprintk(tx_buf, sizeof(tx_buf), "msg %d", i);
        msg.info = i;
        msg.size = strlen(tx_buf) + 1;
        msg.tx_data = tx_buf;
        msg.tx_block = K_NO_WAIT;
        msg.rx_block = K_NO_WAIT;

        k_mbox_async_put(&mbox, &msg, NULL);
        k_sem_give(&sync_sem); /* Signal that put is done */
    }
}

ZTEST_USER_F(mbox_api, test_mbox_async_multiple_put)
{
    k_thread_create(&tthread, tstack, STACK_SIZE,
                    tthread_entry_async_multiple_put, NULL, NULL, NULL,
                    K_PRIO_COOP(7), 0, K_NO_WAIT);
    k_thread_name_set(&tthread, "tthread_async_multiple_put");

    struct k_mbox_msg mmsg;
    void *rx_data;

    for (int i = 0; i < 3; i++) {
        k_sem_take(&sync_sem, K_FOREVER); /* Wait for put to complete */
        k_mbox_get(&mbox, &mmsg, &rx_data, K_FOREVER);

        zassert_equal(mmsg.info, i, "mmsg.info not equal to i");
        zassert_equal(mmsg.size, strlen((char *)rx_data) + 1, "mmsg.size mismatch");
        char expected_buf[MSG_SIZE];
        snprintk(expected_buf, sizeof(expected_buf), "msg %d", i);
        /* Fix: Compare received data against the expected string, not an uninitialized buffer */
        zassert_true(strcmp((char *)rx_data, expected_buf) == 0, "Received data mismatch");
    }

    k_thread_join(&tthread, K_FOREVER);
}

static void tthread_entry_async_put_get_block(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    struct k_mbox_msg msg;
    char tx_buf[MSG_SIZE];

    snprintk(tx_buf, sizeof(tx_buf), "block_msg");
    msg.info = 100;
    msg.size = strlen(tx_buf) + 1;
    msg.tx_data = tx_buf;
    msg.tx_block = K_FOREVER; /* This is the key for this test */
    msg.rx_block = K_NO_WAIT;

    k_mbox_async_put(&mbox, &msg, NULL);
    k_sem_give(&sync_sem); /* Signal that put is done */
}

ZTEST_USER_F(mbox_api, test_mbox_async_put_get_block)
{
    k_thread_create(&tthread, tstack, STACK_SIZE,
                    tthread_entry_async_put_get_block, NULL, NULL, NULL,
                    K_PRIO_COOP(7), 0, K_NO_WAIT);
    k_thread_name_set(&tthread, "tthread_async_put_get_block");

    struct k_mbox_msg mmsg;
    void *rx_data;

    k_sem_take(&sync_sem, K_FOREVER); /* Wait for put to complete */
    k_mbox_get(&mbox, &mmsg, &rx_data, K_FOREVER);

    zassert_equal(mmsg.info, 100, "mmsg.info not equal to 100");
    zassert_equal(mmsg.size, strlen("block_msg") + 1, "mmsg.size mismatch");
    zassert_true(strcmp((char *)rx_data, "block_msg") == 0, "Received data mismatch");

    k_thread_join(&tthread, K_FOREVER);
}

/* Setup and Teardown functions */
static void mbox_api_before(void *fixture)
{
    ARG_UNUSED(fixture);
    k_mbox_init(&mbox);
    k_sem_init(&sync_sem, 0, 1);
}

static void mbox_api_after(void *fixture)
{
    ARG_UNUSED(fixture);
    /* No specific cleanup needed for mbox or sem */
}

ZTEST_SUITE(mbox_api, NULL, NULL, mbox_api_before, mbox_api_after, NULL);
